import { useEffect, useState } from "react";
import MenuGrid from "./MenuGrid";
import Cart from "./Cart";
import UserOrders from "./UserOrders";
import { useAuth } from "../../context/AuthContext";
import Recommendations from "./Recommendations";
import PaymentModal from "./PaymentModal";
import "../../styles/canteen-ui.css";

export default function UserPanel() {
  const { user, logout } = useAuth();
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [showPayment, setShowPayment] = useState(false);

  /* =========================
     CART LOGIC
  ========================= */

  const addToCart = item => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);

      if (existing) {
        return prev.map(i =>
          i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
        );
      }

      return [...prev, { ...item, quantity: 1 }];
    });
  };

  // ✅ NEW — safe, non-breaking
const removeFromCart = (itemId) => {
  setCart((prevCart) =>
    prevCart
      .map((item) =>
        item.id === itemId
          ? { ...item, quantity: item.quantity - 1 }
          : item
      )
      .filter((item) => item.quantity > 0)
  );
};


  /* =========================
     FINAL ORDER 
  ========================= */

  const finalizeOrder = async () => {
    if (!user || cart.length === 0) return;

    const items = cart;
    const total = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
    const order_id = Date.now();

    // Instant UI update
    setOrders(prev => [
      { order_id, items, total, status: "Pending" },
      ...prev
    ]);

    try {
      await fetch("http://localhost:8000/api/orders/create/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          order_id,
          user: user.username,
          items,
          total
        })
      });

      setCart([]);

      // Refresh menu stock (college specific)
      fetch(`http://localhost:8000/api/menu/?college=${user.college}`)
        .then(res => res.json())
        .then(setMenu);

    } catch (err) {
      console.error("Order failed", err);
    }
  };

  /* =========================
     PAYMENT HANDLERS
  ========================= */

  const startPayment = () => {
    if (cart.length === 0) return;
    setShowPayment(true);
  };

  const handlePaymentSuccess = () => {
    setShowPayment(false);
    finalizeOrder();
  };

  const handlePaymentCancel = () => {
    setShowPayment(false);
  };

  /* =========================
     MENU AUTO REFRESH
  ========================= */

  useEffect(() => {
    if (!user) return;

    const loadMenu = () => {
      fetch(`http://localhost:8000/api/menu/?college=${user.college}`)
        .then(res => res.json())
        .then(setMenu)
        .catch(err => console.error("Menu fetch failed", err));
    };

    loadMenu();
    const interval = setInterval(loadMenu, 3000);

    return () => clearInterval(interval);
  }, [user]);

  /* =========================
     ORDER AUTO SYNC
  ========================= */

  useEffect(() => {
    if (!user) return;

    const syncOrders = () => {
      fetch(`http://localhost:8000/api/orders/?user=${user.username}`)
        .then(res => res.json())
        .then(setOrders)
        .catch(() => {});
    };

    syncOrders();
    const interval = setInterval(syncOrders, 2000);

    return () => clearInterval(interval);
  }, [user]);

  /* =========================
     UI
  ========================= */

  if (!user) return null;

  const totalAmount = cart.reduce((s, i) => s + i.price * i.quantity, 0);

  return (
    <div>
      <header>
        <h2>Welcome {user.username}</h2>
        <p style={{ fontSize: "14px", opacity: 0.8 }}>
          College: {user.college}
        </p>
        <button onClick={logout}>Logout</button>
      </header>

      <Recommendations addToCart={addToCart} />

      <MenuGrid
        menu={menu}
        cart={cart}
        addToCart={addToCart}
        removeFromCart={removeFromCart}
      />

      <Cart
        cart={cart}
        removeFromCart={removeFromCart}
        placeOrder={startPayment}
      />

      <UserOrders orders={orders} />

      {showPayment && (
        <PaymentModal
          total={totalAmount}
          onCancel={handlePaymentCancel}
          onSuccess={handlePaymentSuccess}
        />
      )}
    </div>
  );
}
